    fn request(scenario: Scenario) -> ModelRequest {
        let mut req = ModelRequest::new();
        req.messages = vec![Item::UserMessage {
            content: vec![ContentPart::Text {
                text: "What is the weather in Berlin?".into(),
            }],
        }];
